const tenantId = $input.first().json.body.tenant_id;
const eventType = $input.first().json.body.event_type;
const payload = $input.first().json.body.payload;

const configs = {
  tenant_a: {
    tenant_id: "tenant_a",
    name: "E-commerce SMB",
    error_mode: "continue",
    data_handling: "standard",
    email: {
      enabled: true,
      from_name: "TenantA Store",
      templates: {
        cart_abandoned: "tmpl_001",
        new_order: "tmpl_002",
        refund_requested: "tmpl_003"
      }
    },
    sheet_log: {
      enabled: true,
      sheet_id: "sheet_tenant_a"
    },
    slack: {
      enabled: false
    },
    crm: {
      enabled: false
    },
    audit: {
      enabled: false
    }
  },
  tenant_b: {
    tenant_id: "tenant_b",
    name: "B2B SaaS",
    error_mode: "block",
    data_handling: "standard",
    email: {
      enabled: true,
      from_name: "TenantB",
      templates: {
        trial_signup: "tmpl_010",
        upgrade: "tmpl_011",
        churn_signal: "tmpl_012"
      }
    },
    sheet_log: {
      enabled: false
    },
    slack: {
      enabled: true,
      channel: "#new-trials"
    },
    crm: {
      enabled: true,
      record_type: "Lead"
    },
    audit: {
      enabled: false
    }
  },
  tenant_c: {
    tenant_id: "tenant_c",
    name: "Healthcare Provider",
    error_mode: "block",
    data_handling: "pii_masked",
    email: {
      enabled: true,
      from_name: "HealthcareCo",
      templates: {
        appointment_reminder: "tmpl_020",
        intake_completed: "tmpl_021"
      }
    },
    sheet_log: {
      enabled: false
    },
    slack: {
      enabled: false
    },
    crm: {
      enabled: false
    },
    audit: {
      enabled: true
    }
  }
};

const config = configs[tenantId];

if (!config) {
  throw new Error(`Unknown tenant_id: ${tenantId}`);
}

return [{
  json: {
    tenant_config: config,
    event_type: eventType,
    payload: payload
  }
}];

const data = $input.first().json;
const payload = { ...data.payload };

// Fields considered PII
const piiFields = ["customer_email", "patient_name", "dob", "phone", "address"];

for (const field of piiFields) {
  if (payload[field]) {
    payload[field] = "***MASKED***";
  }
}

return [{
  json: {
    ...data,
    payload: payload,
    pii_masked: true
  }
}];

const data = $input.first().json;

const services = ["email", "crm", "slack", "sheet_log", "audit"];

return services.map(service => ({
  json: {
    ...data,
    service: service
  }
}));

const items = $input.all();

const results = {};

for (const item of items) {
  const data = item.json;
  // Check all keys ending in _result
  for (const key of Object.keys(data)) {
    if (key.endsWith('_result')) {
      results[key] = data[key];
    }
  }
}

const firstItem = items[0].json;

return [{
  json: {
    tenant_id: firstItem.tenant_config?.tenant_id || "unknown",
    event_type: firstItem.event_type || "unknown",
    execution_summary: results
  }
}];
